import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { toast } from 'react-toastify';
import { CheckCircle, AlertTriangle, RefreshCw, Database, Users, Package, ShoppingCart, Receipt, FileText, BookOpen, Wallet, BarChart3, AlertCircle } from 'lucide-react';
import { utilityAPI } from '../../services/api';

const MODULE_CONFIG = {
  customers: { label: 'Customers', icon: Users, color: 'blue', checks: ['Missing names', 'Invalid GSTIN format', 'Duplicate name+phone'] },
  products: { label: 'Items', icon: Package, color: 'emerald', checks: ['Zero prices', 'Negative stock', 'Duplicate names'] },
  sales: { label: 'Sales', icon: ShoppingCart, color: 'purple', checks: ['Unpaid invoices', 'Broken customer references'] },
  purchases: { label: 'Purchases', icon: Receipt, color: 'amber', checks: ['Unpaid purchases'] },
  expenses: { label: 'Expenses', icon: FileText, color: 'red', checks: ['Basic validation'] },
  journalEntries: { label: 'Journal Entries', icon: BookOpen, color: 'indigo', checks: ['Unbalanced entries', 'Missing entries for sales'] },
  accounts: { label: 'Chart of Accounts', icon: BarChart3, color: 'cyan', checks: ['Account existence'] },
  stock: { label: 'Stock Movements', icon: Database, color: 'orange', checks: ['Missing history', 'Low stock', 'Negative stock'] },
  transactions: { label: 'Transactions', icon: Wallet, color: 'teal', checks: ['Cash in/out balance'] },
};

const VerifyMyData = () => {
  const [verifying, setVerifying] = useState(false);
  const [verified, setVerified] = useState(false);
  const [results, setResults] = useState([]);
  const [progress, setProgress] = useState(0);

  const runVerification = async () => {
    setVerifying(true); setResults([]); setProgress(0);
    try {
      const res = await utilityAPI.verifyData();
      const data = res.data || {};
      const keys = Object.keys(MODULE_CONFIG);
      const newResults = [];
      for (let i = 0; i < keys.length; i++) {
        setProgress(((i + 1) / keys.length) * 100);
        await new Promise(r => setTimeout(r, 150));
        const key = keys[i];
        const info = data[key] || { count: 0, status: 'warning', issues: [] };
        newResults.push({ id: key, ...MODULE_CONFIG[key], count: info.count || 0, status: info.status || 'warning', issues: info.issues || [] });
      }
      setResults(newResults);
      setVerified(true);
      const allPass = newResults.every(r => r.status === 'pass');
      if (allPass) toast.success('All data checks passed!');
      else toast.warning('Some data issues found. Review below.');
    } catch (err) { toast.error(err.response?.data?.message || 'Verification failed'); }
    finally { setVerifying(false); }
  };

  const allPass = verified && results.length > 0 && results.every(r => r.status === 'pass');
  const totalIssues = results.reduce((acc, r) => acc + r.issues.length, 0);

  return (
    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }}>
      <h1 className="text-xl font-bold text-slate-900 dark:text-[#F8FAFC] mb-6">Verify My Data</h1>
      <div className="bg-white dark:bg-[#1E293B] rounded-2xl border border-slate-200 dark:border-[#334155] shadow-soft p-8">
        {!verified ? (
          <div className="text-center py-12">
            <div className="w-20 h-20 rounded-full bg-blue-100 dark:bg-blue-500/15 flex items-center justify-center mx-auto mb-6"><Database className="w-10 h-10 text-blue-600" /></div>
            <h2 className="text-lg font-bold text-slate-900 dark:text-[#F8FAFC] mb-2">Data Verification</h2>
            <p className="text-sm text-slate-500 dark:text-[#64748B] mb-8 max-w-md mx-auto">This will check all your business data for consistency, missing fields, invalid formats, duplicates, and potential issues across {Object.keys(MODULE_CONFIG).length} modules.</p>
            <div className="grid grid-cols-3 gap-3 max-w-lg mx-auto mb-8 text-left">
              {[
                { label: 'GSTIN Validation', desc: 'Verify 15-char GST format' },
                { label: 'Duplicate Detection', desc: 'Find duplicate customers/items' },
                { label: 'Broken References', desc: 'Detect orphaned records' },
                { label: 'Negative Stock', desc: 'Find items with negative stock' },
                { label: 'Unbalanced Entries', desc: 'Verify debit = credit' },
                { label: 'Cash Balance', desc: 'Verify cash in = cash out' },
              ].map((check, i) => (
                <div key={i} className="flex items-start gap-2 p-2 rounded-lg bg-slate-50 dark:bg-[#0F172A]/40">
                  <AlertCircle className="w-3.5 h-3.5 text-blue-500 mt-0.5 flex-shrink-0" />
                  <div><p className="text-xs font-semibold text-slate-700 dark:text-[#E2E8F0]">{check.label}</p><p className="text-[10px] text-slate-400 dark:text-[#64748B]">{check.desc}</p></div>
                </div>
              ))}
            </div>
            {verifying && (
              <div className="max-w-xs mx-auto mb-6">
                <div className="h-2 bg-slate-100 dark:bg-[#334155] rounded-full overflow-hidden">
                  <motion.div className="h-full bg-blue-600 rounded-full" animate={{ width: `${progress}%` }} transition={{ duration: 0.3 }} />
                </div>
                <p className="text-xs text-slate-400 dark:text-[#64748B] mt-2">Verifying... {Math.round(progress)}%</p>
              </div>
            )}
            <button onClick={runVerification} disabled={verifying} className="px-8 py-3 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 inline-flex items-center gap-2">
              <RefreshCw className={`w-4 h-4 ${verifying ? 'animate-spin' : ''}`} /> {verifying ? 'Verifying...' : 'Start Verification'}
            </button>
          </div>
        ) : (
          <div>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-lg font-bold text-slate-900 dark:text-[#F8FAFC]">Verification Results</h2>
              <button onClick={() => { setVerified(false); setResults([]); }} className="px-4 py-2 text-sm text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-500/10 rounded-lg transition-colors inline-flex items-center gap-2"><RefreshCw className="w-4 h-4" /> Re-verify</button>
            </div>
            {allPass ? (
              <div className="flex items-center gap-3 p-4 bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-200 dark:border-emerald-500/20 rounded-xl mb-6"><CheckCircle className="w-5 h-5 text-emerald-600" /><p className="text-sm font-medium text-emerald-700 dark:text-emerald-300">All data checks passed! Your business data is consistent and complete.</p></div>
            ) : (
              <div className="flex items-center gap-3 p-4 bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/20 rounded-xl mb-6"><AlertTriangle className="w-5 h-5 text-amber-600" /><p className="text-sm font-medium text-amber-700 dark:text-amber-300">{totalIssues} issue(s) found across {results.filter(r => r.issues.length > 0).length} module(s). Review details below.</p></div>
            )}
            <div className="space-y-3">
              {results.map((r) => (
                <div key={r.id} className={`flex items-center gap-4 p-4 rounded-xl border transition-all ${r.status === 'pass' ? 'border-emerald-200 bg-emerald-50/30 dark:border-emerald-500/20 dark:bg-emerald-500/5' : 'border-amber-200 bg-amber-50/30 dark:border-amber-500/20 dark:bg-amber-500/5'}`}>
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${r.status === 'pass' ? 'bg-emerald-100 dark:bg-emerald-500/15' : 'bg-amber-100 dark:bg-amber-500/15'}`}>
                    {r.status === 'pass' ? <CheckCircle className="w-5 h-5 text-emerald-600" /> : <AlertTriangle className="w-5 h-5 text-amber-600" />}
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-semibold text-slate-900 dark:text-[#F8FAFC]">{r.label}</p>
                    <p className="text-xs text-slate-500 dark:text-[#64748B]">{r.count} record(s){r.issues.length > 0 ? ` — ${r.issues.join('; ')}` : ' — All checks passed'}</p>
                  </div>
                  <span className={`text-xs font-semibold px-2.5 py-0.5 rounded-full ${r.status === 'pass' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300' : 'bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300'}`}>
                    {r.status === 'pass' ? 'Passed' : `${r.issues.length} Issue(s)`}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default VerifyMyData;
